const edition = globalThis.makeSubjectEdition({"subject":"golden-fleece","year":2013,"grade":"3-4","contest":"Золотое руно","letters":"ABC","count":60,"language":"ru","points":3,"tasksFile":"ZR_1213_540_3-4.pdf","answersFile":"reviewed-3-4-v540.pdf","title":"Pax Germanica. Единство немецкой стихии","sourceFile":"sources/golden-fleece/2013/interactive-3-4-v540.json","sections":[{"start":1,"title":"История"},{"start":16,"title":"Литература"},{"start":31,"title":"Культура повседневности"},{"start":46,"title":"Города и замки"}],"variant":"540","editionSuffix":"v540","editionLabel":"Сибирь и Дальний Восток","reviewedKey":true}, [{"number":1,"question":"Принято считать, что первое самостоятельное германское государство появилось вследствие … .","choices":["гибели Западной Римской империи","раздела империи Карла I Великого","распада Франкского королевства"],"answer":1,"title":"Раздел большой империи","steps":["В 843 году внуки Карла Великого разделили его державу по Верденскому договору.","Восточная часть досталась Людовику Немецкому. Из неё выросло средневековое Германское королевство."]},{"number":2,"question":"В I веке н. э. произошло сражение между римскими легионами и германскими племенами – битва в Тевтобургском лесу. Какое значение оно имело?","choices":["Было предотвращено вторжение германцев в Галлию","Римляне подчинили германские племена от Рейна до Эльбы","Продвижение римлян вглубь Германии было остановлено"],"answer":2,"title":"Битва в лесу","steps":["Вождь херусков Арминий разбил три римских легиона Вара в 9 году нашей эры.","После этого римляне ещё воевали за Рейном, но приостановили постоянное продвижение вглубь Германии."]},{"number":3,"question":"По легенде, эта птица дала название родовому замку династии Габсбургов.","choices":["Ястреб","Сокол","Лебедь"],"answer":0,"title":"Птица над замком","steps":["Одно из легендарных объяснений названия Габсбург связывает его с немецким Habicht, «ястреб».","По этой версии, название замка означает «ястребиный замок»."]},{"number":4,"question":"Герцогство, а потом королевство Пруссия получило свое название от … .","choices":["Пруса, брата императора Августа","племени пруссов","имени первого герцога Пруссии"],"answer":1,"title":"Откуда имя Пруссии","steps":["У юго-восточного берега Балтики жили древние балтские племена. Позднее их земли завоевал Тевтонский орден.","Название местных пруссов перешло к территории и возникшему на ней государству."]},{"number":5,"question":"По одной из версий, происхождение названия столицы Германии связано с этим животным.","choices":["Бобр","Медведь","Барсук"],"answer":1,"title":"Животное на гербе","steps":["На берлинском гербе изображён чёрный медведь. По-немецки слово «медведь» звучит Bär.","Игра звуков дала народное объяснение названия Берлин. Лингвисты также связывают его со славянским названием болотистой местности."]},{"number":6,"question":"Подписание соглашений Вестфальского мира явилось окончанием … .","choices":["Первой мировой войны","Второй мировой войны","Тридцатилетней войны"],"answer":2,"title":"Мир 1648 года","steps":["Договоры в Мюнстере и Оснабрюке положили конец войне, охватившей германские земли после событий 1618 года.","Война длилась тридцать лет. Поэтому её называют Тридцатилетней."]},{"number":7,"question":"В 1805 году Наполеон одержал победу над союзной армией России и Австрии в битве под … .","choices":["Ульмом","Ватерлоо","Аустерлицем"],"answer":2,"title":"Битва трёх императоров","steps":["В 1805 году Наполеон заставил русско-австрийскую армию оставить удобные позиции и прорвал её центр.","Эта битва под Аустерлицем стала крупнейшей победой Наполеона над Третьей коалицией."]},{"number":8,"question":"Отец этой российской императрицы был прусским фельдмаршалом.","choices":["Екатерина II","Екатерина I","Анна Иоанновна"],"answer":0,"title":"Семья императрицы","steps":["София Августа Фредерика происходила из Ангальт-Цербстского дома. Её отец Христиан Август служил в прусской армии.","После перехода в православие она стала Екатериной Алексеевной, будущей Екатериной II."]},{"number":9,"question":"Этот император Германии правил страной всего 99 дней.","choices":["Вильгельм II","Фридрих III","Вильгельм I"],"answer":1,"title":"Короткое правление","steps":["В 1888 году после Вильгельма I трон перешёл к его тяжело больному сыну. Тот умер в том же году.","Этим императором был Фридрих III. Его сменил Вильгельм II."]},{"number":10,"question":"Этот знаменитый немецкий археолог в 1847 году стал подданным России.","choices":["Г. Шлиман","К. Хуман","В. Дерпфельд"],"answer":0,"title":"Археолог в России","steps":["Будущий исследователь Трои до раскопок занимался торговлей. Он жил в Петербурге и получил российское подданство.","Это немецкий археолог Генрих Шлиман."]},{"number":11,"question":"Этот государственный деятель получил прозвище «железный канцлер».","choices":["О. фон Бисмарк","Б. фон Бюлов","К. фон Меттерних"],"answer":0,"title":"Железный канцлер","steps":["Политик руководил объединением германских государств вокруг Пруссии. После объединения он стал первым канцлером империи.","«Железным канцлером» прозвали Отто фон Бисмарка."]},{"number":12,"question":"В конце XIX века сформировалось это военно-политическое объединение, куда входили Германия, Австро-Венгрия и Италия.","choices":["Антанта","Священный союз","Тройственный союз"],"answer":2,"title":"Три союзника","steps":["В 1882 году Германия и Австро-Венгрия заключили союз с Италией. Участников было трое.","Договор известен как Тройственный союз."]},{"number":13,"question":"Одним из поводов для начала Первой мировой войны стало это событие.","choices":["Внезапное выступление немецких войск против России","Убийство эрцгерцога Франца Фердинанда","Распад Антанты"],"answer":1,"title":"Событие в Сараеве","steps":["В июне 1914 года в Сараеве был убит наследник австро-венгерского престола. В ответ Австро-Венгрия предъявила ультиматум Сербии.","Убийство Франца Фердинанда стало непосредственным поводом к войне."]},{"number":14,"question":"Этот немецкий археолог обнаружил знаменитый Пергамский алтарь, построенный во II веке до н. э. в честь победы греков над племенами варваров.","choices":["Г. Шлиман","К. Хуман","В. Дерпфельд"],"answer":1,"title":"Раскопки в Пергаме","steps":["В Пергаме нашли рельефы, где боги сражаются с гигантами. Раскопки конца XIX века велись немецкой экспедицией.","Ею руководил Карл Хуман, который обнаружил Пергамский алтарь."]},{"number":15,"question":"Это племя дало название одной из земель современной Германии.","choices":["Свевы","Тюринги","Бургунды"],"answer":1,"title":"Имя современной земли","steps":["Одну из центральных земель Германии называют Тюрингией. Название сохраняет память о раннесредневековом населении.","Это население составляли тюринги."]},{"number":16,"question":"Этот писатель создал знаменитую детскую сказку об олененке Бэмби.","choices":["Р.-Э. Распе","Братья Гримм","Ф. Зальтен"],"answer":2,"title":"История оленёнка","steps":["«Бэмби. История жизни в лесу» вышла в 1923 году. Её автор — австрийский писатель и журналист.","Книгу написал Феликс Зальтен. Мультфильм появился позднее."]},{"number":17,"question":"В этой сказке братьев Гримм один из главных героев попросил пекаря вымазать ему ногу тестом.","choices":["«Рапунцель»","«Король-лягушонок»","«Волк и семеро козлят»"],"answer":2,"title":"Лапа в тесте","steps":["Козлята не открывают дверь, если видят чёрную лапу. Волк добивается, чтобы его лапа выглядела белой.","Сцена с пекарем есть в сказке «Волк и семеро козлят»."]},{"number":18,"question":"Сколько бременских музыкантов описывается в сказке братьев Гримм?","choices":["Четыре","Пять","Шесть"],"answer":0,"title":"Состав музыкантов","steps":["От первого хозяина уходит осёл, а в дороге к нему присоединяются пёс, кот и петух.","Осёл, пёс, кот и петух — четверо."]},{"number":19,"question":"Какую работу должна была каждый день делать падчерица в сказке братьев Гримм «Госпожа Метелица»?","choices":["Убирать светлицу","Готовить завтрак","Прясть пряжу"],"answer":2,"title":"Ежедневная работа","steps":["В начале сказки падчерица сидит у колодца с веретеном. Она роняет веретено и прыгает за ним.","Инструмент выдаёт её ежедневное занятие — прядение пряжи."]},{"number":20,"question":"В сказке братьев Гримм король Дроздобород появлялся перед королевной в этом образе.","choices":["Знатный князь","Бедный музыкант","Простой дворянин"],"answer":1,"title":"Переодетый король","steps":["Капризную принцессу выдают за бедного человека, который пришёл к дворцу. Он зарабатывает песней и игрой.","Позже выясняется, что музыкантом притворился сам король Дроздобород."]},{"number":21,"question":"Каких животных завещал своим сыновьям крестьянин из сказки братьев Гримм «Три счастливца»?","choices":["Лошадь, свинья","Осел, собака","Петух, кошка"],"answer":2,"title":"Скромное наследство","steps":["Отец передаёт троим сыновьям петуха, косу и кошку. Каждый предмет оказывается полезен там, где о нём раньше не знали.","Животных в списке два — петух и кошка."]},{"number":22,"question":"Это мифическое животное приказал поймать король портному в сказке братьев Гримм «Храбрый портной».","choices":["Единорог","Дракон","Кентавр"],"answer":0,"title":"Поручение портному","steps":["Портной заманивает опасное существо к дереву. Оно бросается на него и застревает рогом в стволе.","Один рог выдаёт единорога."]},{"number":23,"question":"Этот герой французского эпоса стал главным персонажем поэмы И. В. Гёте.","choices":["Роланд","Рейнеке-Лис","Лесной царь"],"answer":1,"title":"Хитрец из эпоса","steps":["В сказаниях о животных главный герой побеждает противников хитростью. У Гёте он участвует в тяжбах при дворе зверей.","Гёте назвал поэму «Рейнеке-Лис»."]},{"number":24,"question":"У этого животного, по словам Мюнхгаузена, на голове выросло дерево.","choices":["Олень","Волк","Лошадь"],"answer":0,"title":"Дерево на голове","steps":["Барон стреляет в животное вишнёвой косточкой. Позже он снова встречает его и видит, что косточка дала росток.","Вишнёвое дерево якобы выросло на голове оленя."]},{"number":25,"question":"Каким образом барону Мюнхгаузену в одной из рассказанных им историй удалось выбраться из болота?","choices":["По веревке","Его вытащила лошадь","Он вытянул сам себя за волосы"],"answer":2,"title":"Выход из болота","steps":["В обычном мире выбраться без внешней опоры так невозможно. Герой специально рассказывает невероятную историю как правду.","Он уверяет, что вытянул себя и коня за собственные волосы."]},{"number":26,"question":"В каком деле больше всего преуспел Карлик Нос в сказке В. Гауфа?","choices":["Садоводство","Кулинария","Рыболовство"],"answer":1,"title":"Искусство героя","steps":["После превращения герой попадает на службу к герцогу. Он умеет готовить такие блюда, каких придворные прежде не пробовали.","У Карлика Носа особенно хорошо получалась кулинария."]},{"number":27,"question":"Трава, с помощью которой мог быть расколдован Карлик Нос, росла только под этим деревом.","choices":["Дуб","Каштан","Ель"],"answer":1,"title":"Трава против чар","steps":["Гусыня Мими помогает герою искать особую траву, которой недостаёт для паштета. Её запах разрушает чары.","В сказке траву находят под каштаном."]},{"number":28,"question":"Кто из героев немецких сказок стал личным скороходом короля благодаря волшебным туфлям?","choices":["Калиф-аист","Барон Мюнхгаузен","Маленький Мук"],"answer":2,"title":"Обувь скорохода","steps":["Волшебные туфли позволяют преодолевать большие расстояния необычайно быстро. Их владелец выигрывает состязание при дворе.","Скороходом делается Маленький Мук."]},{"number":29,"question":"В сказке «Калиф-аист» В. Гауфа вернуть человеческий облик калифу и визирю, превращенным в аистов, помогла … .","choices":["сова","черепаха","ящерица"],"answer":0,"title":"Помощница в руинах","steps":["Герои забыли волшебное слово и не могут снова стать людьми. Заколдованная принцесса помогает им подслушать это слово.","Принцесса живёт в облике совы."]},{"number":30,"question":"В сказке Э. Т. А. Гофмана Мари, защищая Щелкунчика, кинула в мышей этот предмет.","choices":["Книгу","Подсвечник","Туфлю"],"answer":2,"title":"Защитница Щелкунчика","steps":["Мыши уже теснят войско игрушек. Мари бросает первое, что может снять с ноги и бросить на расстояние.","Она бросает в мышиного короля туфлю."]},{"number":31,"question":"Согласно легенде, именно ему принадлежит идея приносить в дом и украшать рождественскую ель.","choices":["Э. Т. А. Гофман","М. Лютер","Я. Гримм"],"answer":1,"title":"Рождественская легенда","steps":["В предании немецкий реформатор увидел свет звёзд среди ветвей и принёс домой дерево со свечами.","Так возникла легенда о рождественской ели Мартина Лютера."]},{"number":32,"question":"Немецкий изобретатель И. Гутенберг известен как создатель … .","choices":["печатного станка","парового двигателя","гидравлического пресса"],"answer":0,"title":"Изобретение в Майнце","steps":["Изобретатель наладил европейскую печать с помощью отдельного набора подвижных литер. Одним из первых больших изданий стала Библия.","Гутенберг известен именно развитием печатного станка."]},{"number":33,"question":"Старинное название этого европейского города означает «малый город».","choices":["Люксембург","Гамбург","Аугсбург"],"answer":0,"title":"Старинное имя города","steps":["В раннем названии Lucilinburhuc вторая часть означает укрепление, а первая указывает на малые размеры.","От названия небольшой крепости произошло название Люксембурга."]},{"number":34,"question":"В этом городе родился знаменитый австрийский композитор В. А. Моцарт, автор опер «Свадьба Фигаро», «Дон Жуан» и «Волшебная флейта».","choices":["Зальцбург","Вена","Линц"],"answer":0,"title":"Город Моцарта","steps":["В этом городе на улице Гетрайдегассе сохранился дом семьи композитора. Моцарт родился там в 1756 году.","Дом-музей стоит в Зальцбурге."]},{"number":35,"question":"О каком композиторе Л. ван Бетховен говорил: «Не ручей – море должно было быть ему имя»?","choices":["В. А. Моцарт","Й. Гайдн","И. С. Бах"],"answer":2,"title":"Ручей или море","steps":["Слово Bach по-немецки означает «ручей». Бетховен обыграл фамилию композитора, считая его музыку гораздо значительнее ручья.","Речь об Иоганне Себастьяне Бахе."]},{"number":36,"question":"Этот композитор полностью лишился слуха, но это не помешало ему создавать всемирно известные музыкальные произведения.","choices":["Ф. Мендельсон","В. А. Моцарт","Л. ван Бетховен"],"answer":2,"title":"Музыка без слуха","steps":["Композитор продолжал работать, хотя постепенно почти полностью оглох. Поздние сонаты и Девятая симфония появились в этот период.","Их написал Людвиг ван Бетховен."]},{"number":37,"question":"Этот немецкий аристократ создал особенную конструкцию дирижабля, и такие аппараты стали называть его именем.","choices":["Ф. Цеппелин","И. Этрих","Х. Юнкерс"],"answer":0,"title":"Дирижабль с каркасом","steps":["Воздушный корабль изобретателя имел прочный каркас и отдельные газовые камеры.","Такие корабли назвали цеппелинами в честь Фердинанда фон Цеппелина."]},{"number":38,"question":"В одном из московских музеев есть такие экспонаты, как бешеная шуба, пистолет, стреляющий от искры из глаза, и рожок, в котором сперва замерзли, а потом оттаяли звуки. Какому литературному персонажу он посвящен?","choices":["Шерлок Холмс","Пиноккио","Барон Мюнхгаузен"],"answer":2,"title":"Необычные экспонаты","steps":["Все вещи происходят из рассказов, где невозможный случай подан как обычное приключение. В одном рассказе звуки оживают после оттепели.","Такие истории рассказывал барон Мюнхгаузен."]},{"number":39,"question":"Одним из официальных языков Швейцарии является … .","choices":["испанский","английский","итальянский"],"answer":2,"title":"Языки Швейцарии","steps":["Швейцария признаёт немецкий, французский, итальянский и ретороманский национальными языками.","Из предложенных вариантов верен итальянский. На нём говорят, в частности, в кантоне Тичино."]},{"number":40,"question":"Какая птица была изображена на гербе графов Швангау и является одним из ведущих мотивов декоративного оформления замка Нойшванштайн?","choices":["Чайка","Орел","Лебедь"],"answer":2,"title":"Птица на гербе","steps":["Название Швангау напоминает слово Schwan, «лебедь». Лебедь связан и с легендой о рыцаре Лоэнгрине, которую любил Людвиг II.","Поэтому лебедь повторяется в убранстве Нойшванштайна."]},{"number":41,"question":"Из этого зала каждый год 1 января транслируется на весь мир «Новогодний концерт» Венского филармонического оркестра.","choices":["Серебряный зал","Золотой зал","Янтарный зал"],"answer":1,"title":"Зал новогоднего концерта","steps":["Филармоники выступают в здании Венского музыкального общества. Интерьер главного зала обильно украшен позолотой.","Зал называется Золотым."],"figure":{"src":"assets/golden-fleece/2013/interactive-3-4-540/41.webp","alt":"Зал новогоднего концерта · Иллюстрация к заданию 41 · Современный снимок того же объекта","caption":"Иллюстрация к заданию 41 · Современный снимок того же объекта","detailSrc":"assets/golden-fleece/2013/interactive-3-4-540/41-detail.webp","width":620,"height":413}},{"number":42,"question":"В 1898 году возле Чертова моста в швейцарской части Альп был открыт памятник в честь этого русского полководца и его армии.","choices":["А. Румянцев","М. Кутузов","А. Суворов"],"answer":2,"title":"Поход через Альпы","steps":["Русское войско пересекло Альпы в 1799 году. Бой у Чёртова моста связан с этим переходом.","Монумент посвящён полководцу Александру Суворову и его войску."],"figure":{"src":"assets/golden-fleece/2013/interactive-3-4-540/42.webp","alt":"Поход через Альпы · Иллюстрация к заданию 42","caption":"Иллюстрация к заданию 42","width":136,"height":111}},{"number":43,"question":"В этом музее находятся ворота Иштар, обнаруженные при раскопках Вавилона.","choices":["Немецкий исторический музей","Берлинская картинная галерея","Пергамский музей"],"answer":2,"title":"Ворота из Вавилона","steps":["На синих глазурованных кирпичах ворот видны рельефы животных. Найденные фрагменты собрали в Берлине.","Ворота Иштар установлены в Пергамском музее."],"figure":{"src":"assets/golden-fleece/2013/interactive-3-4-540/43.webp","alt":"Ворота из Вавилона · Иллюстрация к заданию 43","caption":"Иллюстрация к заданию 43","width":133,"height":107}},{"number":44,"question":"В каком австрийском городе в XVIII веке парк Мирабель украсили забавными фигурами карликов?","choices":["Зальцбург","Инсбрук","Грац"],"answer":0,"title":"Фигуры в парке","steps":["Дворец и сады Мирабель известны барочными композициями и отдельным садом с фигурами карликов.","Ансамбль Мирабель находится в Зальцбурге."],"figure":{"src":"assets/golden-fleece/2013/interactive-3-4-540/44.webp","alt":"Фигуры в парке · Иллюстрация к заданию 44","caption":"Иллюстрация к заданию 44","width":135,"height":109}},{"number":45,"question":"В этом музее, расположенном в немецком городе Гиссен, можно оказаться в гигантском мыльном пузыре, познакомиться с миром зеркальных иллюзий и прикоснуться ко всем экспонатам руками.","choices":["Музей игрушек","Обергессенский музей","Математикум"],"answer":2,"title":"Музей опытов","steps":["Экспонаты устроены как математические опыты: посетитель строит, сравнивает и наблюдает. Мыльная плёнка показывает форму поверхности.","Интерактивный музей Гиссена называется «Математикум»."],"figure":{"src":"assets/golden-fleece/2013/interactive-3-4-540/45.webp","alt":"Музей опытов · Иллюстрация к заданию 45","caption":"Иллюстрация к заданию 45","width":132,"height":105}},{"number":46,"question":"Этот город считается финансовым центром континентальной Европы.","choices":["Кёльн","Бремен","Франкфурт-на-Майне"],"answer":2,"title":"Финансовый центр","steps":["В городе расположены биржа и Европейский центральный банк. Его высокие банковские здания узнают на фоне реки Майн.","Это Франкфурт-на-Майне."],"figure":{"src":"assets/golden-fleece/2013/interactive-3-4-540/46.webp","alt":"Финансовый центр · Иллюстрация к заданию 46","caption":"Иллюстрация к заданию 46","width":133,"height":109}},{"number":47,"question":"В этом городе находится церковь, для которой в 1970 году М. Шагал создал 5 витражей на библейские сюжеты.","choices":["Люксембург","Вена","Цюрих"],"answer":2,"title":"Витражи Шагала","steps":["Пять длинных витражей на библейские сюжеты установлены в хоре церкви Фраумюнстер.","Эта церковь находится в Цюрихе."],"figure":{"src":"assets/golden-fleece/2013/interactive-3-4-540/47.webp","alt":"Витражи Шагала · Иллюстрация к заданию 47","caption":"Иллюстрация к заданию 47","width":133,"height":108}},{"number":48,"question":"В этом городе, в церкви Святого Фомы, более 25 лет работал великий немецкий композитор И. С. Бах.","choices":["Веймар","Лейпциг","Берлин"],"answer":1,"title":"Кантор церкви","steps":["Бах руководил хором школы Святого Фомы и сочинял музыку для богослужений. Он работал здесь с 1723 года до смерти.","Школа и церковь Святого Фомы находятся в Лейпциге."],"figure":{"src":"assets/golden-fleece/2013/interactive-3-4-540/48.webp","alt":"Кантор церкви · Иллюстрация к заданию 48","caption":"Иллюстрация к заданию 48","width":132,"height":104}},{"number":49,"question":"Этот дворец, согласно легенде, получил свое название от родника с ключевой водой, который во время охоты обнаружил император Маттиас.","choices":["Нимфенбург","Шёнбрунн","Сан-Суси"],"answer":1,"title":"Родник у дворца","steps":["В немецком названии schön означает «красивый», а Brunnen — «источник» или «колодец».","По легенде, имя венского дворца Шёнбрунн связано с таким источником."],"figure":{"src":"assets/golden-fleece/2013/interactive-3-4-540/49.webp","alt":"Родник у дворца · Иллюстрация к заданию 49","caption":"Иллюстрация к заданию 49","width":132,"height":104}},{"number":50,"question":"Этот город на рубеже XVIII–XIX вв. был центром немецкого Просвещения, а перед его Оперным театром установлен памятник И. В. Гёте и Ф. Шиллеру.","choices":["Гамбург","Веймар","Берлин"],"answer":1,"title":"Город поэтов","steps":["Гёте и Шиллер жили и работали при дворе одного небольшого немецкого государства. Их совместный памятник стоит перед Национальным театром.","Памятник находится в Веймаре."],"figure":{"src":"assets/golden-fleece/2013/interactive-3-4-540/50.webp","alt":"Город поэтов · Иллюстрация к заданию 50","caption":"Иллюстрация к заданию 50","width":132,"height":105}},{"number":51,"question":"Этот дворец был частной резиденцией Фридриха II, а с 1991 года является местом его погребения.","choices":["Цициленхоф","Сан-Суси","Райнсберг"],"answer":1,"title":"Летняя резиденция","steps":["Фридрих II построил дворец на виноградных террасах в Потсдаме. Французское имя означает «без забот».","Это Сан-Суси, где по его желанию устроили могилу."],"figure":{"src":"assets/golden-fleece/2013/interactive-3-4-540/51.webp","alt":"Летняя резиденция · Иллюстрация к заданию 51","caption":"Иллюстрация к заданию 51","width":132,"height":104}},{"number":52,"question":"В этом городе находится мост-улица, на котором расположено более 30 домов.","choices":["Эрфурт","Гамбург","Франкфурт-на-Майне"],"answer":0,"title":"Мост как улица","steps":["По обе стороны мостовой стоят дома, а посередине проходит улица торговцев. Мост называется Кремербрюке.","Такой мост сохранился в Эрфурте."],"figure":{"src":"assets/golden-fleece/2013/interactive-3-4-540/52.webp","alt":"Мост как улица · Иллюстрация к заданию 52","caption":"Иллюстрация к заданию 52","width":132,"height":107}},{"number":53,"question":"Этот замок в настоящее время является музеем, который ежегодно посещает более миллиона туристов.","choices":["Берг","Левенбург","Нойшванштайн"],"answer":2,"title":"Замок над ущельем","steps":["Замок с белыми стенами и башнями был задуман Людвигом II как романтическая резиденция. Он стоит на горном выступе.","Теперь посетители осматривают его как музей Нойшванштайн."],"figure":{"src":"assets/golden-fleece/2013/interactive-3-4-540/53.webp","alt":"Замок над ущельем · Иллюстрация к заданию 53","caption":"Иллюстрация к заданию 53","width":136,"height":112}},{"number":54,"question":"В этом замке благодаря специальным механизмам стол поднимался из кухни в столовую уже накрытым, что позволяло обойтись без присутствия слуг за обедом.","choices":["Херренкимзее","Нойшванштайн","Линдерхоф"],"answer":2,"title":"Стол без слуг","steps":["Механизм поднимал накрытый стол с нижнего этажа прямо в столовую. Король мог обедать один.","Стол такого устройства сохранился в Линдерхофе."],"figure":{"src":"assets/golden-fleece/2013/interactive-3-4-540/54.webp","alt":"Стол без слуг · Иллюстрация к заданию 54","caption":"Иллюстрация к заданию 54","width":132,"height":105}},{"number":55,"question":"В этом городе находится готический собор, который считается самым высоким в мире.","choices":["Любек","Ульм","Кёльн"],"answer":1,"title":"Высота собора","steps":["У собора огромная западная башня со шпилем высотой около 161,5 метра. Такой высоты она достигла после достройки в XIX веке.","Это готический собор Ульма."],"figure":{"src":"assets/golden-fleece/2013/interactive-3-4-540/55.webp","alt":"Высота собора · Иллюстрация к заданию 55","caption":"Иллюстрация к заданию 55","width":131,"height":105}},{"number":56,"question":"Одной из главных достопримечательностей этого города являются античные ворота, построенные древними римлянами.","choices":["Мюнхен","Трир","Любек"],"answer":1,"title":"Римские ворота","steps":["Два башенных объёма ворот соединены каменными переходами. Тёмный цвет дал памятнику имя Порта-Нигра.","Римские ворота Порта-Нигра находятся в Трире."],"figure":{"src":"assets/golden-fleece/2013/interactive-3-4-540/56.webp","alt":"Римские ворота · Иллюстрация к заданию 56","caption":"Иллюстрация к заданию 56","width":132,"height":105}},{"number":57,"question":"В нескольких километрах от этого города находится Вальхалла – Зал Славы, посвященный выдающимся личностям германской истории и культуры.","choices":["Кёльн","Гамбург","Регенсбург"],"answer":2,"title":"Зал славы над Дунаем","steps":["Вальхалла выглядит как древнегреческий храм. Внутри собраны бюсты выдающихся людей германской истории.","Она стоит у Дуная недалеко от Регенсбурга."],"figure":{"src":"assets/golden-fleece/2013/interactive-3-4-540/57.webp","alt":"Зал славы над Дунаем · Иллюстрация к заданию 57","caption":"Иллюстрация к заданию 57","width":132,"height":106}},{"number":58,"question":"В этом городе расположен архитектурный ансамбль, который украшают изображения Красной Шапочки, Кота в Сапогах и Спящей красавицы.","choices":["Берлин","Зальцбург","Франкфурт-на-Майне"],"answer":0,"title":"Сказки в парке","steps":["В большом фонтанном ансамбле герои сказок выстроены по краям воды. Это Фонтан сказок в Народном парке Фридрихсхайн.","Парк с таким фонтаном находится в Берлине."],"figure":{"src":"assets/golden-fleece/2013/interactive-3-4-540/58.webp","alt":"Сказки в парке · Иллюстрация к заданию 58","caption":"Иллюстрация к заданию 58","width":132,"height":105}},{"number":59,"question":"В этом городе находится архитектурный ансамбль в стиле барокко, который был украшен скульптурными изображениями животных и птиц из белого фарфора в натуральную величину.","choices":["Мюнхен","Берлин","Дрезден"],"answer":2,"title":"Дворец и фарфор","steps":["Саксонский правитель Август Сильный собирал фарфор. Барочные дома дворцового ансамбля теперь хранят часть коллекции.","Этот ансамбль, Цвингер, расположен в Дрездене."],"figure":{"src":"assets/golden-fleece/2013/interactive-3-4-540/59.webp","alt":"Дворец и фарфор · Иллюстрация к заданию 59","caption":"Иллюстрация к заданию 59","width":132,"height":104}},{"number":60,"question":"Одной из главных достопримечательностей этого города является ратуша в неоготическом стиле.","choices":["Кёльн","Бонн","Мюнхен"],"answer":2,"title":"Неоготическая ратуша","steps":["Самая заметная ратуша на Мариенплац имеет высокую фасадную башню и часы с движущимися фигурами.","Это Новая ратуша Мюнхена."],"figure":{"src":"assets/golden-fleece/2013/interactive-3-4-540/60.webp","alt":"Неоготическая ратуша · Иллюстрация к заданию 60","caption":"Иллюстрация к заданию 60","width":132,"height":105}}]);
